#define SIN(x) ((sin(x) + 1.0) / 2.0)
#define PI 3.14159

#define ZOOM_DIR 0
//#define ZOOM_DIR 1
//#define ZOOM_DIR 2

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    float aspect = iResolution.x / iResolution.y;

#if ZOOM_DIR==0
    //float tilesX = max(sin((iTime - PI * 2.0) / 10.0) * 80.0, 1.0);
    // float tilesX = (1.-log(abs(sin(iTime/10.))/log(3.))*70.);
    float tilesX = mix(10.,150.,0.5+0.5*sin(iTime*0.1));
    float intensity = 1.;
#endif
#if ZOOM_DIR==1
    float n = iTime / 10.;
    float loopDuration = 80.;
    float blackDuration = 20.;
    float zoomSpeed = 35.;
    float tilesX = max((loopDuration - blackDuration) - fract(log(n)*zoomSpeed) * loopDuration, 0.);
    float intensity = 1.;
#endif
#if ZOOM_DIR==2
    float n = fract(iTime / 10.);
    float loopDuration = 80.;
    float m = fract(log(n));
    float tilesX = max(loopDuration - m * loopDuration, 0.);
    float intensity = 1.-m;
#endif
    if (tilesX==0.) return;
    vec2 tileCount = vec2(tilesX * aspect, tilesX);

    vec2 center = vec2(0.5, 0.5);
    vec2 tileUv = fract((uv - center) * tileCount + center);
    vec2 tileCoord = floor((uv - center) * tileCount);

    #define AAstep(x, y) smoothstep(x - blur, x + blur, y)
    float blur = 1.0 / iResolution.y;

    float outlineThickness = 0.01 / (9.0 / tilesX);
    vec2 distToEdge = min(tileUv, 1.0 - tileUv);
    float minDistToEdge = min(distToEdge.x, distToEdge.y);
    float edgeMask = AAstep(outlineThickness, minDistToEdge);
    float crossMask = AAstep(abs(tileUv.x - 0.5), outlineThickness) + AAstep(abs(tileUv.y - 0.5), outlineThickness);
    float outlineMask = 1.0 - edgeMask + crossMask;

    // Grid-based wave: waves aligned to the tile grid
    float waveX = sin(tileCoord.x * 2.0 + iTime);
    float waveY = sin(tileCoord.y * 2.0 + iTime);
    float spiralOffset = waveX + waveY;  // Combined to create a "ripple" pattern aligned with the grid
//float spiralOffset = sin(float(tileCoord.x + tileCoord.y) * 2.0 + iTime);
//float randomFactor = fract(sin(dot(tileCoord, vec2(12.9898, 78.233))) * 43758.5453);
//float spiralOffset = sin((tileCoord.x + tileCoord.y + randomFactor) * 2.0 + iTime);

    float timeStep = mod(iTime, 4.0);
    int currentQuadrant = int(floor(timeStep + spiralOffset));

    int[] remap = int[](2, 0, 1, 3);
    currentQuadrant = remap[currentQuadrant % 4];
    int nextQuadrant = remap[(currentQuadrant + 1) % 4];

    vec2 quadrant = floor(tileUv * 2.0);
    int quadIndex = int(quadrant.x) + 2 * int(quadrant.y);

    float blendFactor = fract(iTime);

    vec3 colors[4];
    colors[0] = vec3(1.0, 0.4, 0.4);  // Red
    colors[1] = vec3(0.4, 1.0, 0.4);  // Green
    colors[2] = vec3(0.4, 0.4, 1.0);  // Blue
    colors[3] = vec3(1.0, 1.0, 0.4);  // Yellow

    vec3 color = vec3(0.1);
    if (quadIndex == currentQuadrant)
        color = colors[currentQuadrant];

    float inSquare = step(0.0, tileUv.x) * step(0.0, tileUv.y) * step(tileUv.x, 1.0) * step(tileUv.y, 1.0);
    fragColor = vec4(color * inSquare * intensity, 1.0);
}
